/////////////////////////////////
// cp_mprvinst
//   Execute ecall and ebreak
//   Should cause an exception
/////////////////////////////////

Sm_mprivinst_cg_cp_mprvinst_ecall:
  ecall                 # test ecall instruction
  nop                   # this is skipped after trap handler returns

Sm_mprivinst_cg_cp_mprvinst_ebreak:
  ebreak                # test ebreak instruction
  nop                   # this is skipped after trap handler returns


/////////////////////////////////
// cp_mret
//   Execute mret while sweeping cross-product of mpp, mprv, mpie, mie
/////////////////////////////////

  CSRR(x11, mstatus)        # read and save mstatus
  # set up x13 with mstatus except MPP, MPRV, MPIE, MIE cleared
  LI(x12, 0x21888)          # x12 has all MPP, MPRV, MPIE, MIE bits set (bits [12:11], [17], [7], [3], respectively)
  not x12, x12              # x12 has all but MPP, MPRV, MPIE, MIE bits set
  and x13, x11, x12         # clear MPP, MPRV, MPIE, MIE bits

# mret with mpp = 11 mprv = 0 mpie = 0 mie = 0
  LI(x14, 0x00001800)
  or x14, x14, x13         # value to write to mstatus with MPP/MPRV/MPIE/MIE bits set/clear
  LA(x8, 1f)              # return address after mret
  CSRW(mepc, x8)          # set mepc to return address
  CSRW(mstatus, x14)       # write mstatus with MPP/MPRV/MPIE/MIE bits set/clear
Sm_mprivinst_cg_cp_mret_mpp_11_mprv_0_mpie_0_mie_0_wval:
  mret                     # test mret instruction
  addi x14, zero, -1       # should not be executed
1:                         # mret should return to here
  # Check if x14 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x14, Sm_mprivinst_cg_cp_mret_mpp_11_mprv_0_mpie_0_mie_0_wval, Sm_mprivinst_cg_cp_mret_mpp_11_mprv_0_mpie_0_mie_0_wval_str)
Sm_mprivinst_cg_cp_mret_mpp_11_mprv_0_mpie_0_mie_0_rval:
  # Read mstatus into x14 and check against expected.
  RVTEST_SIGUPD_CSR_READ(mstatus, x14, Sm_mprivinst_cg_cp_mret_mpp_11_mprv_0_mpie_0_mie_0_rval, Sm_mprivinst_cg_cp_mret_mpp_11_mprv_0_mpie_0_mie_0_rval_str)

# mret with mpp = 11 mprv = 0 mpie = 0 mie = 1
  LI(x14, 0x00001808)
  or x14, x14, x13         # value to write to mstatus with MPP/MPRV/MPIE/MIE bits set/clear
  LA(x8, 1f)              # return address after mret
  CSRW(mepc, x8)          # set mepc to return address
  CSRW(mstatus, x14)       # write mstatus with MPP/MPRV/MPIE/MIE bits set/clear
Sm_mprivinst_cg_cp_mret_mpp_11_mprv_0_mpie_0_mie_1_wval:
  mret                     # test mret instruction
  addi x14, zero, -1       # should not be executed
