/////////////////////////////////
// cp_mcsr_access
//   Read, write all 1s, write all 0s, set all 1s, set all 0s, restore all M-mode CSRs
/////////////////////////////////

# CSR Access Tests for mstatus
  CSRR(x13, mstatus)    # Save CSR
  LI(x14, -1)          # x14 = all 1s
#if __riscv_xlen == 64
  LI(x10, 0xffffffcfffffffbf)    # Load 64-bit mask
#else
  LI(x10, 0xffffffbf)   # Load 32-bit mask (upper bits of 0xffffffcfffffffbf are ignored)
#endif
Sm_mcsr_cg_cp_mcsr_access_mstatus_csrrw1:
  CSRW(mstatus, x14)    # Write all 1s to CSR
  # Read mstatus into x12, keep only bits specified by mask, and check against expected.
  CSRR(x12, mstatus)    # Read CSR
  and x12, x12, x10    # keep only masked bits 0xffffffcfffffffbf
  # Check if x12 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x12, Sm_mcsr_cg_cp_mcsr_access_mstatus_csrrw1, Sm_mcsr_cg_cp_mcsr_access_mstatus_csrrw1_str)

Sm_mcsr_cg_cp_mcsr_access_mstatus_csrrw0:
  CSRW(mstatus, zero)   # Write all 0s to CSR
  # Read mstatus into x12, keep only bits specified by mask, and check against expected.
  CSRR(x12, mstatus)    # Read CSR
  and x12, x12, x10    # keep only masked bits 0xffffffcfffffffbf
  # Check if x12 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x12, Sm_mcsr_cg_cp_mcsr_access_mstatus_csrrw0, Sm_mcsr_cg_cp_mcsr_access_mstatus_csrrw0_str)

Sm_mcsr_cg_cp_mcsr_access_mstatus_csrs_all:
  CSRS(mstatus, x14)    # Set all CSR bits
  # Read mstatus into x12, keep only bits specified by mask, and check against expected.
  CSRR(x12, mstatus)    # Read CSR
  and x12, x12, x10    # keep only masked bits 0xffffffcfffffffbf
  # Check if x12 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x12, Sm_mcsr_cg_cp_mcsr_access_mstatus_csrs_all, Sm_mcsr_cg_cp_mcsr_access_mstatus_csrs_all_str)

