  CSRC(mstatus, x14)    # Clear all CSR bits
  # Read mstatus into x12, keep only bits specified by mask, and check against expected.
  CSRR(x12, mstatus)    # Read CSR
  and x12, x12, x10    # keep only masked bits 0xffffffcfffffffbf
