  RVTEST_SIGUPD(x2, x5, x4, x12, Sm_mcsr_cg_cp_mcsr_access_mstatus_csrrc_all, Sm_mcsr_cg_cp_mcsr_access_mstatus_csrrc_all_str)
  CSRW(mstatus, x13)       # Restore CSR

# CSR Access Tests for medeleg
