/////////////////////////////////
// cp_misa_mxl
//   Set, clear, write misa.MXL.  Should not change
/////////////////////////////////
# Save misa
  csrr x14, misa      # save misa
# Load 1s into msb and msb-1 corresponding to misa.MXL bitfields
  LI(x15, -1)           # all 1s
  srli x15, x15, 1  # all 1s except msb = 0
  not x15, x15      # 1 in msb (works regardless of XLEN)
  srli x8, x15, 1 # 1s in msb-1
  or x13, x15, x8 # 1s in both msb and msb-1

Sm_mcsr_cg_cp_misa_mxl_csrc_11:
  csrc misa, x13       # attempt to clear both MXL bits
  csrr x11, misa          # read misa to check MXL bits are unchanged
  and x11, x11, x13 # mask off bits below MXL
  # Check if x11 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x11, Sm_mcsr_cg_cp_misa_mxl_csrc_11, Sm_mcsr_cg_cp_misa_mxl_csrc_11_str)

Sm_mcsr_cg_cp_misa_mxl_csrs_11:
  csrs misa, x13       # attempt to set both MXL bits
  csrr x11, misa          # read misa to check MXL bits are unchanged
  and x11, x11, x13 # mask off bits below MXL
  # Check if x11 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x11, Sm_mcsr_cg_cp_misa_mxl_csrs_11, Sm_mcsr_cg_cp_misa_mxl_csrs_11_str)

Sm_mcsr_cg_cp_misa_mxl_csrw_00:
  csrw misa, zero           # attempt to write 00 to MXL bits
  csrr x11, misa          # read misa to check MXL bits are unchanged
  and x11, x11, x13 # mask off bits below MXL
  # Check if x11 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x11, Sm_mcsr_cg_cp_misa_mxl_csrw_00, Sm_mcsr_cg_cp_misa_mxl_csrw_00_str)

Sm_mcsr_cg_cp_misa_mxl_csrw_01:
  csrw misa, x8       # attempt to write 01 to MXL bits
  csrr x11, misa          # read misa to check MXL bits are unchanged
  and x11, x11, x13 # mask off bits below MXL
  # Check if x11 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x11, Sm_mcsr_cg_cp_misa_mxl_csrw_01, Sm_mcsr_cg_cp_misa_mxl_csrw_01_str)

Sm_mcsr_cg_cp_misa_mxl_csrw_10:
  csrw misa, x15        # attempt to write 10 to MXL bits
  csrr x11, misa          # read misa to check MXL bits are unchanged
  and x11, x11, x13 # mask off bits below MXL
  # Check if x11 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x11, Sm_mcsr_cg_cp_misa_mxl_csrw_10, Sm_mcsr_cg_cp_misa_mxl_csrw_10_str)

Sm_mcsr_cg_cp_misa_mxl_csrw_11:
  csrw misa, x13       # attempt to write 11 to MXL bits
  csrr x11, misa          # read misa to check MXL bits are unchanged
  and x11, x11, x13 # mask off bits below MXL
  # Check if x11 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
