  csrw misa, x14    # restore misa


/////////////////////////////////
// cp_misa_dependencies
//   Attempt to write incompatible values to misa and check illegal combinations do not occur
/////////////////////////////////
# Write I = 1, E = 1. Error if this reads back the same.
  LI(x15, 0b00000000000000000100010000) # Illegal value to write to misa and read back
  LI(x13, 0b00000000000000000100010000) # bits to check
Sm_mcsr_cg_cp_misa_dependencies_i1e1:
  csrw misa, x15 # attempt to write misa
  csrr x10, misa # read back
  and x10, x10, x13 # Mask off don't care bits
  xor x10, x10, x15 # Zero result means failing condition observed
  seqz x10, x10  # 1 indicates illegal outcome.  Ref model should always produce 0
  # Check if x10 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x10, Sm_mcsr_cg_cp_misa_dependencies_i1e1, Sm_mcsr_cg_cp_misa_dependencies_i1e1_str)

# Write I = 0, E = 0. Error if this reads back the same.
  LI(x8, 0b00000000000000000000000000) # Illegal value to write to misa and read back
  LI(x13, 0b00000000000000000000000000) # bits to check
Sm_mcsr_cg_cp_misa_dependencies_i0e0:
  csrw misa, x8 # attempt to write misa
  csrr x11, misa # read back
  and x11, x11, x13 # Mask off don't care bits
  xor x11, x11, x8 # Zero result means failing condition observed
  seqz x11, x11  # 1 indicates illegal outcome.  Ref model should always produce 0
  # Check if x11 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x11, Sm_mcsr_cg_cp_misa_dependencies_i0e0, Sm_mcsr_cg_cp_misa_dependencies_i0e0_str)

# Write F=0, D = 1. Error if this reads back the same.
  LI(x12, 0b00000000000000000000001000) # Illegal value to write to misa and read back
  LI(x15, 0b00000000000000000000101000) # bits to check
Sm_mcsr_cg_cp_misa_dependencies_f0d1:
  csrw misa, x12 # attempt to write misa
  csrr x10, misa # read back
  and x10, x10, x15 # Mask off don't care bits
  xor x10, x10, x12 # Zero result means failing condition observed
  seqz x10, x10  # 1 indicates illegal outcome.  Ref model should always produce 0
  # Check if x10 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x10, Sm_mcsr_cg_cp_misa_dependencies_f0d1, Sm_mcsr_cg_cp_misa_dependencies_f0d1_str)

# Write F=1, D = 0, Q = 1. Error if this reads back the same.
  LI(x8, 0b00000000010000000000100000) # Illegal value to write to misa and read back
  LI(x12, 0b00000000010000000000101000) # bits to check
Sm_mcsr_cg_cp_misa_dependencies_f1d0q1:
  csrw misa, x8 # attempt to write misa
  csrr x11, misa # read back
  and x11, x11, x12 # Mask off don't care bits
  xor x11, x11, x8 # Zero result means failing condition observed
  seqz x11, x11  # 1 indicates illegal outcome.  Ref model should always produce 0
  # Check if x11 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x11, Sm_mcsr_cg_cp_misa_dependencies_f1d0q1, Sm_mcsr_cg_cp_misa_dependencies_f1d0q1_str)

# Write S = 1, U = 0. Error if this reads back the same.
  LI(x12, 0b00000001000000000000000000) # Illegal value to write to misa and read back
  LI(x10, 0b00000101000000000000000000) # bits to check
Sm_mcsr_cg_cp_misa_dependencies_s1u0:
  csrw misa, x12 # attempt to write misa
  csrr x8, misa # read back
  and x8, x8, x10 # Mask off don't care bits
  xor x8, x8, x12 # Zero result means failing condition observed
  seqz x8, x8  # 1 indicates illegal outcome.  Ref model should always produce 0
  # Check if x8 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x8, Sm_mcsr_cg_cp_misa_dependencies_s1u0, Sm_mcsr_cg_cp_misa_dependencies_s1u0_str)

# Write H = 1, S = 0. Error if this reads back the same.
  LI(x12, 0b00000000000000000010000000) # Illegal value to write to misa and read back
  LI(x11, 0b00000001000000000010000000) # bits to check
Sm_mcsr_cg_cp_misa_dependencies_h1s0:
  csrw misa, x12 # attempt to write misa
  csrr x13, misa # read back
  and x13, x13, x11 # Mask off don't care bits
  xor x13, x13, x12 # Zero result means failing condition observed
  seqz x13, x13  # 1 indicates illegal outcome.  Ref model should always produce 0
  # Check if x13 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x13, Sm_mcsr_cg_cp_misa_dependencies_h1s0, Sm_mcsr_cg_cp_misa_dependencies_h1s0_str)

# Write H = 1, S = 1, U = 0. Error if this reads back the same.
  LI(x12, 0b00000001000000000010000000) # Illegal value to write to misa and read back
  LI(x8, 0b00000101000000000010000000) # bits to check
Sm_mcsr_cg_cp_misa_dependencies_h1s1u0:
