/////////////////////////////////
// cp_misa_clear_c
//   Try to clear misa.C.  Should not change if PC is at 2-byte aligned address
/////////////////////////////////
  LI(x10, 0b100)      # bitmask for C extension bit in misa

  csrs misa, x10     # set misa.C if possible
  csrr x12, misa          # read misa to check if misa.C was set
  and x12, x12, x10 # mask off all but C bit
  .align 2 # 4-byte alignment
Sm_mcsr_cg_cp_misa_clear_c_pc_1_0:
  csrc misa, x10      # attempt to clear misa.C with misa.C = 1 and PC 4-byte aligned
  csrr x11, misa          # read misa to check misa.C changed if writable
  and x11, x11, x10 # mask off all but C bit
  xor x11, x11, x12 # check if misa.C differed before and after clear attempt; might be 4 if misa.C is mutable because it is allowed to differ when PC is 4-byte aligned
  # Check if x11 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x11, Sm_mcsr_cg_cp_misa_clear_c_pc_1_0, Sm_mcsr_cg_cp_misa_clear_c_pc_1_0_str)

#ifdef ZCA_SUPPORTED
  csrs misa, x10     # set misa.C if possible
  csrr x12, misa          # read misa to check if misa.C was set
  and x12, x12, x10 # mask off all but C bit
  .align 2 # 4-byte alignment
  .half 0x0001            # c.nop, can't write that directly because Zca not enabled for Sm
Sm_mcsr_cg_cp_misa_clear_c_pc_1_1:
  csrc misa, x10      # attempt to clear misa.C with misa.C = 1 and PC 2-byte aligned
  csrr x11, misa          # read misa to check misa.C didn't change
  .align 2
  and x11, x11, x10 # mask off all but C bit
  xor x11, x11, x12 # check if misa.C differed before and after clear attempt; should be 0 because writing misa.C is not allowed to differ when PC is 2-byte aligned
  # Check if x11 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x11, Sm_mcsr_cg_cp_misa_clear_c_pc_1_1, Sm_mcsr_cg_cp_misa_clear_c_pc_1_1_str)
#endif
  csrw misa, x14    # restore misa

#ifdef SM1P13P0_SUPPORTED


/////////////////////////////////
// cp_misa_bv
//   Sm1p13: misa.B (bit 1) and misa.V (bit 21) correctness.
//   Read, set, and clear each bit; read back and write to signature.
/////////////////////////////////
  csrr x13, misa       # save misa before Sm1p13 B/V tests
  LI(x11, 0x2)                 # bitmask for misa.B (bit 1)
  LI(x12, 0x200000)            # bitmask for misa.V (bit 21)

# Set misa.B and read back
Sm_mcsr_cg_cp_misa_bv_set_B:
  csrs misa, x11              # attempt to set misa.B
  csrr x14, misa             # read back misa
  and x14, x14, x11     # isolate misa.B
  # Check if x14 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x14, Sm_mcsr_cg_cp_misa_bv_set_B, Sm_mcsr_cg_cp_misa_bv_set_B_str)

# Clear misa.B and read back
Sm_mcsr_cg_cp_misa_bv_clr_B:
  csrc misa, x11              # attempt to clear misa.B
  csrr x14, misa             # read back misa
  and x14, x14, x11     # isolate misa.B
  # Check if x14 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x14, Sm_mcsr_cg_cp_misa_bv_clr_B, Sm_mcsr_cg_cp_misa_bv_clr_B_str)

# Set misa.V and read back
Sm_mcsr_cg_cp_misa_bv_set_V:
  csrs misa, x12              # attempt to set misa.V
  csrr x14, misa             # read back misa
  and x14, x14, x12     # isolate misa.V
  # Check if x14 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x14, Sm_mcsr_cg_cp_misa_bv_set_V, Sm_mcsr_cg_cp_misa_bv_set_V_str)

# Clear misa.V and read back
Sm_mcsr_cg_cp_misa_bv_clr_V:
  csrc misa, x12              # attempt to clear misa.V
  csrr x14, misa             # read back misa
  and x14, x14, x12     # isolate misa.V
  # Check if x14 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x14, Sm_mcsr_cg_cp_misa_bv_clr_V, Sm_mcsr_cg_cp_misa_bv_clr_V_str)

  csrw misa, x13      # restore misa after B/V tests


/////////////////////////////////
// cp_msip
//   Sm1p13: write all 1s / all 0s to memory-mapped msip register.
//   Read back msip, wait, then read mip.MSIP; must reflect the written value.
/////////////////////////////////
#ifdef RVMODEL_MSIP_ADDRESS
  LI(x11, RVMODEL_MSIP_ADDRESS)   # load address of memory-mapped msip register

# Write 1 to msip (set MSIP) and check mip.MSIP is set
  LI(x10, 1)                         # value 1: assert msip
Sm_mcsr_cg_cp_msip_msip_mmio_1:
  SW x10, 0(x11)           # write msip = 1 via memory-mapped I/O
  LW x10, 0(x11)            # read back memory-mapped msip register
  andi x10, x10, 1              # isolate bit 0
  # Check if x10 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x10, Sm_mcsr_cg_cp_msip_msip_mmio_1, Sm_mcsr_cg_cp_msip_msip_mmio_1_str)
