  nop
  nop
  nop # wait a bit
Sm_mcsr_cg_cp_inhibit_mcycle:
  CSRR(x11, mcycle)        # read mcycle again
  sub x11, x11, x12          # difference should be 0
  # Check if x11 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x11, Sm_mcsr_cg_cp_inhibit_mcycle, Sm_mcsr_cg_cp_inhibit_mcycle_str)


/////////////////////////////////
// cp_inhibit_minstret
//   Inhibit minstret
/////////////////////////////////
  LI(x12, 0b100)        # inhibit minstret
  CSRW(mcountinhibit, x12)        # inhibit minstret
  CSRR(x12, minstret)        # read minstret
  nop
  nop
  nop
  nop
  nop
  nop # wait a bit
Sm_mcsr_cg_cp_inhibit_minstret:
  CSRR(x11, minstret)        # read minstret again
  sub x11, x11, x12          # difference should be 0
  # Check if x11 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x11, Sm_mcsr_cg_cp_inhibit_minstret, Sm_mcsr_cg_cp_inhibit_minstret_str)


/////////////////////////////////
// cp_mtime_write
//   Write mtime and read back time if supported
/////////////////////////////////
#ifdef RVMODEL_MTIME_ADDRESS
  LI(x12, 42)        # value to write to mtime
  LA(x11, RVMODEL_MTIME_ADDRESS)        # load address of mtime
  SREG x12, 0(x11)        # write mtime = 42 using memory-mapped I/O
Sm_mcsr_cg_cp_mtime_write:
  CSRR(x11, time)        # read time
  sub x11, x11, x12          # difference should be small
  slti x11, x11, 10          # signature is 1 if difference < 10
  # Check if x11 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x11, Sm_mcsr_cg_cp_mtime_write, Sm_mcsr_cg_cp_mtime_write_str)

#if __riscv_xlen == 32
  LI(x12, 67)        # value to write to mtimeh
  LA(x11, RVMODEL_MTIME_ADDRESS)        # load address of mtimeh
  SREG x12, 4(x11)        # write mtimeh = 67 using memory-mapped I/O
Sm_mcsr_cg_cp_mtime_write_h:
  CSRR(x11, timeh)        # read timeh
  sub x11, x11, x12          # difference should be zero
  # Check if x11 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x11, Sm_mcsr_cg_cp_mtime_write_h, Sm_mcsr_cg_cp_mtime_write_h_str)
#endif
#endif


/////////////////////////////////
// Enable Counters
//   Ensure mcountinhibit is 0 so counters can run
/////////////////////////////////
  LI(x12, 0)                      # Load 0 (enable all counters)
  CSRW(mcountinhibit, x12)        # Clear inhibit register
  nop
  nop
  nop


/////////////////////////////////
// cp_mcycle_wraparound
//   Write max value to mcycle and verify it wraps around cleanly
/////////////////////////////////
#if __riscv_xlen == 64
  LI(x11, -1)                    # Load 0xFFFFFFFFFFFFFFFF
Sm_mcsr_cg_cp_mcycle_wraparound_mcycle_wrap_64:
  CSRW(mcycle, x11)              # Set mcycle to max value
  nop                                   # Force an instruction increment
  CSRR(x12, mcycle)               # Read wrapped value
  sub x12, x12, x11    # Subtract max value to get wrapped value
  sltiu x12, x12, 0xFF       # Signature = 1 if wrapped value < 255
  # Check if x12 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x12, Sm_mcsr_cg_cp_mcycle_wraparound_mcycle_wrap_64, Sm_mcsr_cg_cp_mcycle_wraparound_mcycle_wrap_64_str)
#else // __riscv_xlen == 32
  LI(x11, -1)                    # Load 0xFFFFFFFF
Sm_mcsr_cg_cp_mcycle_wraparound_mcycle_wrap_32:
  CSRW(mcycleh, x11)             # Set upper bits to max FIRST
  CSRW(mcycle, x11)              # Set lower bits to max LAST
  nop                                   # instruction increment to cause wrap
  CSRR(x14, mcycle)              # Read lower bits of wrapped value
  CSRR(x12, mcycleh)              # Check if upper bits wrapped to 0
  sub x12, x12, x11    # Subtract max value to get wrapped value
  sltiu x12, x12, 2          # Signature = 1 if upper bits wrapped to 0 or 1
  # Check if x12 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x12, Sm_mcsr_cg_cp_mcycle_wraparound_mcycle_wrap_32, Sm_mcsr_cg_cp_mcycle_wraparound_mcycle_wrap_32_str)
#endif



/////////////////////////////////
// cp_minstret_wraparound
//   Write max value to minstret and verify it wraps around cleanly
/////////////////////////////////
#if __riscv_xlen == 64
  LI(x11, -1)                    # Load 0xFFFFFFFFFFFFFFFF
Sm_mcsr_cg_cp_minstret_wraparound_minstret_wrap_64:
  CSRW(minstret, x11)            # Set minstret to max value
  nop                                   # Force an instruction increment
  CSRR(x12, minstret)             # Read wrapped value
  sub x12, x12, x11    # Subtract max value to get wrapped value
  sltiu x12, x12, 0xFF       # Signature = 1 if wrapped value < 255
  # Check if x12 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x12, Sm_mcsr_cg_cp_minstret_wraparound_minstret_wrap_64, Sm_mcsr_cg_cp_minstret_wraparound_minstret_wrap_64_str)
#else // __riscv_xlen == 32
  LI(x11, -1)                    # Load 0xFFFFFFFF
Sm_mcsr_cg_cp_minstret_wraparound_minstret_wrap_32:
  CSRW(minstreth, x11)           # Set upper bits to max
  CSRW(minstret, x11)            # Set lower bits to max
  nop                                   # Force increment / overflow
  CSRR(x14, minstret)            # Read lower bits of wrapped value
  CSRR(x12, minstreth)            # Check if upper bits wrapped to 0
  sub x12, x12, x11    # Subtract max value to get wrapped value
  sltiu x12, x12, 2          # Signature = 1 if upper bits wrapped to 0 or 1
  # Check if x12 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x12, Sm_mcsr_cg_cp_minstret_wraparound_minstret_wrap_32, Sm_mcsr_cg_cp_minstret_wraparound_minstret_wrap_32_str)
#endif



/////////////////////////////////
// cp_mtime_wraparound
//   Write max value to memory-mapped mtime and read wrapped value via time CSR
/////////////////////////////////
#ifdef RVMODEL_MTIME_ADDRESS
  LA(x11, RVMODEL_MTIME_ADDRESS) # Load base address of mtime
  LI(x12, -1)                     # Load max integer pattern
#if __riscv_xlen == 64
  SREG x12, 0(x11)          # Write 64-bit max value to mtime register
mtime_wait_64_tc7271:
  CSRR(x12, time)                 # Read shadow CSR time
  LI(x11, 0xFF)                  # Upper bound threshold
  bgeu x12, x11, mtime_wait_64_tc7271 # If still large, keep waiting
Sm_mcsr_cg_cp_mtime_wraparound_mtime_wrap_64:
  LI(x12, 1)                      # Write success signature
  # Check if x12 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x12, Sm_mcsr_cg_cp_mtime_wraparound_mtime_wrap_64, Sm_mcsr_cg_cp_mtime_wraparound_mtime_wrap_64_str)
#else // __riscv_xlen == 32
  SREG x12, 4(x11)          # Write upper 32-bit max
  SREG x12, 0(x11)          # Write lower 32-bit max
mtime_wait_32_tc7271:
  CSRR(x14, time)                # Read shadow CSR time (lower 32 bits)
  CSRR(x12, timeh)                # Read shadow CSR timeh
  LI(x11, 2)
  bgeu x12, x11, mtime_wait_32_tc7271 # Wait for high bits to clear
Sm_mcsr_cg_cp_mtime_wraparound_mtime_wrap_32:
  LI(x12, 1)                      # Write success signature
  # Check if x12 contains the expected result. x2 is the signature ptr, x5 is the link ptr, x4 is a temp reg.
  RVTEST_SIGUPD(x2, x5, x4, x12, Sm_mcsr_cg_cp_mtime_wraparound_mtime_wrap_32, Sm_mcsr_cg_cp_mtime_wraparound_mtime_wrap_32_str)
#endif
#endif


